tools.example:
tf = sltest.testmanager.load('controller_tests.mldatx');
results = run(tf);
disp(results.getTestCaseResults().Outcome);

tf = sltest.testmanager.TestFile('regression.mldatx');
ts = createTestSuite(tf, 'Controller');
tc = createTestCase(ts, 'baseline', 'StepResponse');
setProperty(tc, 'Model', 'controller');
captureBaselineCriteria(tc, 'baseline_step.mat', true);
saveToFile(tf);

tc = createTestCase(ts, 'simulation', 'Nominal');
setProperty(tc, 'Model', 'controller', 'HarnessName', 'controller_Harness1', 'HarnessOwner', 'controller/PID');
res = run(tc);

load_system('controller');
sltest.harness.create('controller/PID', 'Name', 'PID_TS', 'Source', 'Test Sequence', 'Sink', 'Test Assessment');
sltest.harness.open('controller/PID', 'PID_TS');

sltest.harness.open('controller/PID', 'PID_TS');
sim('PID_TS');
sltest.harness.close('controller/PID', 'PID_TS');

add_block('sltestlib/Test Sequence', [mdl '/TS']);
sltest.testsequence.addSymbol([mdl '/TS'], 'u', 'Data', 'Output');
sltest.testsequence.editStep([mdl '/TS'], 'step_1', 'Action', 'u = 0;');
sltest.testsequence.addStep([mdl '/TS'], 'step_2', 'Action', 'u = 1;');
sltest.testsequence.addTransition([mdl '/TS'], 'step_1', 'after(1, sec)', 'step_2');

rs = slreq.new('CruiseReqs');
r1 = add(rs, 'Id', 'CC-1', 'Summary', 'Maintain set speed', 'Description', 'Error < 1 km/h in steady state');
r2 = add(r1, 'Id', 'CC-1.1', 'Summary', 'Overshoot < 5%');
save(rs);

rs = slreq.load('CruiseReqs.slreqx');
reqs = find(rs, 'Type', 'Requirement');
{reqs.Id}

rs = slreq.load('CruiseReqs.slreqx');
req = find(rs, 'Type', 'Requirement', 'Id', 'CC-1');
link = slreq.createLink(get_param('cruise/Controller', 'Handle'), req);
link.Type = 'Implement';
save(link.linkSet);

unlinked = [];
reqs = slreq.find('Type', 'Requirement');
for r = reqs
    if isempty(slreq.inLinks(r)), unlinked = [unlinked r]; end
end

opts = slreq.getReportOptions;
opts.reportPath = fullfile(pwd, 'reqs.docx');
opts.openReport = false;
slreq.generateReport(slreq.load('CruiseReqs.slreqx'), opts);

t = cvtest('controller');
t.label = 'Nominal';
t.settings.decision = 1; t.settings.condition = 1; t.settings.mcdc = 1;
cov = cvsim(t);
cvhtml('cov_report', cov);

covTotal = covA + covB;          % union
newOnly  = covB - covA;          % coverage achieved only by B
cvhtml('delta', newOnly);

c = decisioninfo(cov, 'controller');
pct = 100 * c(1) / c(2);
assert(pct >= 90, 'Decision coverage %.1f%% below target', pct);

simIn = Simulink.SimulationInput('controller');
simIn = simIn.setModelParameter('CovEnable', 'on', 'CovMetricStructuralLevel', 'MCDC', ...
    'CovSaveSingleToWorkspaceVar', 'on', 'CovSaveName', 'covData');
out = sim(simIn);
cvhtml('cov', out.covData);

opts = sldvoptions;
opts.Mode = 'TestGeneration';
opts.ModelCoverageObjectives = 'MCDC';
opts.MaxProcessTime = 600;
opts.SaveHarnessModel = 'on';
[status, files] = sldvrun('controller', opts);

if sldvcompat('controller', sldvoptions)
    sldvrun('controller');
end

[~, files] = sldvrun('controller', opts);
[out, cov] = sldvruntest('controller', files.DataFile, [], true);
cvhtml('sldv_cov', cov);

% drive with a logical requirement signal, e.g. (brake && speed>0) implies throttle==0
% Values: true
opts = sldvoptions; opts.Mode = 'PropertyProving';
sldvrun('controller', opts);

s = Simulink.CloneDetection.Settings();
s.IgnoreSignalName = true;
res = Simulink.CloneDetection.findClones('bigModel', s);
Simulink.CloneDetection.replaceClones(res);

obj = slslicer('controller');
addStartingPoint(obj, 'controller/Throttle Cmd');
activate(obj);
highlight(obj);
terminate(obj);
